// On-demand LinkedIn text: follow the user prompt directly.
// Memory / saved sources / tone are used only when useMemory=true (automation).
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { resolveTextProvider, xaiErrorMessage } from "../_shared/ai-text.ts";
import { gatherSourceContext, type SourceInput } from "../_shared/web-sources.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};
const json = (s: number, b: unknown) => new Response(JSON.stringify(b), { status: s, headers: { ...corsHeaders, "Content-Type": "application/json" } });

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
  try {
    const body = await req.json();
    const {
      prompt,
      currentText,
      imageUrl,
      mode,
      sources,
      savedSourceIds,
      useMemory = false,
    } = body;

    const supabase = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
    const auth = req.headers.get("Authorization");
    if (!auth) return json(401, { success: false, error: "Unauthorized" });
    const { data: u } = await supabase.auth.getUser(auth.replace("Bearer ", ""));
    const userId = u.user?.id;
    if (!userId) return json(401, { success: false, error: "Unauthorized" });

    const { data: s } = await supabase.from("user_settings")
      .select("post_model, use_byok, openai_api_key, xai_api_key, gemini_api_key, firecrawl_api_key, tone_instructions")
      .eq("user_id", userId).maybeSingle();

    const automated = useMemory === true;
    let resolvedSources: SourceInput[] = Array.isArray(sources) ? sources : [];

    if (automated && Array.isArray(savedSourceIds) && savedSourceIds.length) {
      const { data: saved } = await supabase
        .from("content_sources")
        .select("id, source_type, value")
        .eq("user_id", userId)
        .in("id", savedSourceIds);
      for (const r of saved || []) {
        if (r.source_type === "url" || r.source_type === "keyword" || r.source_type === "idea") {
          resolvedSources.push({ type: r.source_type as SourceInput["type"], value: r.value });
        }
      }
    } else if (!automated && Array.isArray(savedSourceIds) && savedSourceIds.length) {
      // Explicit picks in the Composer are intentional context, not automatic memory.
      const { data: saved } = await supabase
        .from("content_sources")
        .select("id, source_type, value")
        .eq("user_id", userId)
        .in("id", savedSourceIds);
      for (const r of saved || []) {
        if (r.source_type === "url" || r.source_type === "keyword" || r.source_type === "idea") {
          resolvedSources.push({ type: r.source_type as SourceInput["type"], value: r.value });
        }
      }
    }

    if (automated && !resolvedSources.length) {
      const { data: enabled } = await supabase
        .from("content_sources")
        .select("source_type, value")
        .eq("user_id", userId)
        .eq("enabled", true)
        .limit(8);
      for (const r of enabled || []) {
        if (r.source_type === "url" || r.source_type === "keyword" || r.source_type === "idea") {
          resolvedSources.push({ type: r.source_type as SourceInput["type"], value: r.value });
        }
      }
    }

    const promptText = typeof prompt === "string" ? prompt.trim() : "";
    let sourceContext = "";
    let sourceProvider: "firecrawl" | "open" = "open";
    let researchUrls: string[] = [];

    if (mode !== "improve" && resolvedSources.length) {
      const gathered = await gatherSourceContext(resolvedSources, { firecrawlKey: s?.firecrawl_api_key });
      sourceContext = gathered.context;
      sourceProvider = gathered.provider;
      researchUrls = gathered.freshUrls;
    }

    const { model, url, key } = resolveTextProvider(s?.post_model || "google/gemini-3-flash-preview", s);
    const hasResearch = sourceContext.trim().length > 40;
    const tone = automated && s?.tone_instructions?.trim() ? s.tone_instructions.trim() : "";

    const sys = `Follow the user's instructions exactly. Write the LinkedIn post they asked for.
Do not add branding, CTAs, hashtags, emojis, length rules, or structure unless the user requested them.
Return JSON via the write_post tool (title + content).
${tone ? `\nAutomation voice/memory from settings:\n${tone}` : ""}
${hasResearch ? "Optional reference material is provided below — use it only if it helps satisfy the user request." : ""}`;

    const sourceBlock = hasResearch
      ? `\n\n--- Reference material ---\n${sourceContext.substring(0, 20000)}\n--- End ---`
      : "";

    let userMsg: unknown;
    if (mode === "improve" && currentText) {
      userMsg = `Improve this LinkedIn draft according to the instructions.\n\nDraft:\n${currentText}\n\nInstructions: ${promptText || "Polish clarity and flow."}${sourceBlock}`;
    } else if (imageUrl) {
      userMsg = [
        { type: "text", text: `${promptText || "Write a LinkedIn post about this image."}${sourceBlock}` },
        { type: "image_url", image_url: { url: imageUrl } },
      ];
    } else {
      userMsg = `${promptText || "Write a LinkedIn post."}${sourceBlock}`;
    }

    const res = await fetch(url, {
      method: "POST",
      headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        model,
        messages: [{ role: "system", content: sys }, { role: "user", content: userMsg }],
        tools: [{
          type: "function",
          function: {
            name: "write_post",
            description: "Return the LinkedIn post",
            parameters: {
              type: "object",
              properties: {
                title: { type: "string", description: "Short internal title" },
                content: { type: "string", description: "Full LinkedIn post body as requested" },
              },
              required: ["title", "content"],
              additionalProperties: false,
            },
          },
        }],
        tool_choice: { type: "function", function: { name: "write_post" } },
      }),
    });
    if (!res.ok) {
      if (url.startsWith("https://api.x.ai/")) return json(res.status, { success: false, error: xaiErrorMessage(res.status) });
      if (res.status === 429) return json(429, { success: false, error: "Rate limit exceeded." });
      if (res.status === 402) return json(402, { success: false, error: "Add credits to your workspace." });
      const t = await res.text();
      return json(500, { success: false, error: `AI error [${res.status}]: ${t}` });
    }

    const data = await res.json();
    const tc = data.choices?.[0]?.message?.tool_calls?.[0];
    if (!tc) return json(500, { success: false, error: "AI returned no structured data" });
    const out = JSON.parse(tc.function.arguments);
    return json(200, {
      success: true,
      title: out.title,
      content: out.content,
      usedSources: resolvedSources.length,
      sourceProvider,
      hadWebContext: hasResearch,
      researchUrlCount: researchUrls.length,
      usedMemory: automated,
    });
  } catch (e) {
    console.error("compose-text error", e);
    return json(500, { success: false, error: e instanceof Error ? e.message : "Failed" });
  }
});

export type TextSettings = {
  use_byok?: boolean;
  openai_api_key?: string | null;
  xai_api_key?: string | null;
  gemini_api_key?: string | null;
};

function requireByok(settings: TextSettings | null) {
  if (!settings?.use_byok) {
    throw new Error("Active tes propres clés API (BYOK) dans les paramètres pour générer du contenu.");
  }
}

/** Route text generation to the user's BYOK provider (xAI / OpenAI / Gemini). No shared gateway. */
export function resolveTextProvider(model: string, settings: TextSettings | null) {
  if (model.startsWith("xai/")) {
    requireByok(settings);
    if (!settings?.xai_api_key?.trim()) {
      throw new Error("Ajoute et enregistre ta clé API xAI dans les paramètres pour utiliser Grok.");
    }
    return {
      model: model.slice(4),
      url: "https://api.x.ai/v1/chat/completions",
      key: settings.xai_api_key.trim(),
    };
  }

  if (model.startsWith("openai/")) {
    requireByok(settings);
    if (!settings?.openai_api_key?.trim()) {
      throw new Error("Ajoute et enregistre ta clé API OpenAI dans les paramètres.");
    }
    return {
      model: model.slice(7),
      url: "https://api.openai.com/v1/chat/completions",
      key: settings.openai_api_key.trim(),
    };
  }

  if (model.startsWith("google/")) {
    requireByok(settings);
    if (!settings?.gemini_api_key?.trim()) {
      throw new Error("Ajoute et enregistre ta clé API Google Gemini dans les paramètres.");
    }
    return {
      model: model.replace(/^google\//, ""),
      url: "https://generativelanguage.googleapis.com/v1beta/openai/chat/completions",
      key: settings.gemini_api_key.trim(),
    };
  }

  throw new Error(
    `Modèle non supporté: ${model}. Choisis un modèle Gemini, OpenAI ou Grok dans les réglages (BYOK).`,
  );
}

export function normalizeGrokModels(models: unknown, modality: "text" | "image" = "text"): { value: string; label: string }[] {
  if (!Array.isArray(models)) return [];
  const ids = new Set<string>();
  for (const model of models) {
    if (!model || typeof model !== "object") continue;
    const { id, aliases, output_modalities } = model as {
      id?: unknown;
      aliases?: unknown;
      output_modalities?: unknown;
    };
    if (Array.isArray(output_modalities) && !output_modalities.includes(modality)) continue;
    for (const name of [id, ...(Array.isArray(aliases) ? aliases : [])]) {
      if (typeof name === "string" && /^[a-zA-Z0-9._-]+$/.test(name)) ids.add(name);
    }
  }
  return [...ids].sort().map((id) => ({ value: `xai/${id}`, label: `Grok · ${id} (API xAI)` }));
}

export function xaiErrorMessage(status: number) {
  if (status === 401) return "Clé API xAI invalide ou expirée. Remplace-la dans les paramètres.";
  if (status === 402) return "Crédits xAI insuffisants. Recharge ton compte xAI.";
  if (status === 403) return "Accès xAI refusé : vérifie les permissions de ta clé et l’accès au modèle.";
  if (status === 404) return "Ce modèle Grok n’est plus disponible. Actualise la liste dans les paramètres.";
  if (status === 429) return "Limite de requêtes xAI atteinte. Réessaie plus tard.";
  if (status === 503) return "Le modèle Grok est temporairement surchargé. Réessaie plus tard.";
  return `La requête xAI a échoué (${status}). Vérifie le modèle et réessaie.`;
}

/**
 * Web source gathering: Firecrawl when a key is available, otherwise free open fallbacks
 * (Jina Reader for URLs, Google News RSS + DuckDuckGo HTML for keyword search).
 */

export type SourceInput = { type: "url" | "keyword" | "idea"; value: string };

export type GatherOptions = {
  /** Prefer user's BYOK Firecrawl key, then env FIRECRAWL_API_KEY. */
  firecrawlKey?: string | null;
  maxUrls?: number;
  maxKeywords?: number;
  /** Skip search results whose URL is in this set (schedules dedupe). */
  usedUrls?: Set<string>;
  urlSnippetChars?: number;
};

function resolveFirecrawlKey(explicit?: string | null): string {
  return (explicit ?? "").trim() || (Deno.env.get("FIRECRAWL_API_KEY") ?? "").trim();
}

function stripTags(html: string): string {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, " ")
    .trim();
}

function decodeXml(s: string): string {
  return s
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, "$1")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

/** Scrape a single URL → markdown/text. */
export async function scrapeUrl(url: string, firecrawlKey?: string | null): Promise<string | null> {
  const fc = resolveFirecrawlKey(firecrawlKey);
  if (fc) {
    try {
      const r = await fetch("https://api.firecrawl.dev/v2/scrape", {
        method: "POST",
        headers: { Authorization: `Bearer ${fc}`, "Content-Type": "application/json" },
        body: JSON.stringify({ url, formats: ["markdown"], onlyMainContent: true, waitFor: 1500 }),
      });
      if (r.ok) {
        const d = await r.json();
        const md = d.data?.markdown || d.markdown;
        if (md) return String(md);
      }
    } catch (e) {
      console.warn("firecrawl scrape fail", url, e);
    }
  }

  // Free: Jina Reader (no API key required for basic use)
  try {
    const r = await fetch(`https://r.jina.ai/${url}`, {
      headers: { Accept: "text/plain", "User-Agent": "market-pulse-poster/1.0" },
    });
    if (r.ok) {
      const text = await r.text();
      if (text.trim().length > 80) return text;
    }
  } catch (e) {
    console.warn("jina scrape fail", url, e);
  }

  // Last resort: raw HTML → text
  try {
    const r = await fetch(url, {
      headers: { "User-Agent": "Mozilla/5.0 (compatible; MarketPulseBot/1.0)", Accept: "text/html" },
      redirect: "follow",
    });
    if (!r.ok) return null;
    const html = await r.text();
    const text = stripTags(html);
    return text.length > 80 ? text : null;
  } catch (e) {
    console.warn("raw scrape fail", url, e);
    return null;
  }
}

export type SearchHit = { title: string; description: string; url: string };

/** Keyword web search → list of hits. */
export async function searchKeyword(query: string, firecrawlKey?: string | null, limit = 3): Promise<SearchHit[]> {
  const fc = resolveFirecrawlKey(firecrawlKey);
  if (fc) {
    try {
      const r = await fetch("https://api.firecrawl.dev/v2/search", {
        method: "POST",
        headers: { Authorization: `Bearer ${fc}`, "Content-Type": "application/json" },
        body: JSON.stringify({ query, limit: Math.max(limit, 5), tbs: "qdr:w" }),
      });
      if (r.ok) {
        const d = await r.json();
        const results = d.data || d.web?.results || [];
        const hits = results
          .map((x: { title?: string; description?: string; url?: string }) => ({
            title: x.title || "",
            description: x.description || "",
            url: x.url || "",
          }))
          .filter((x: SearchHit) => x.url);
        if (hits.length) return hits.slice(0, limit);
      }
    } catch (e) {
      console.warn("firecrawl search fail", query, e);
    }
  }

  // Free: Google News RSS
  try {
    const rssUrl =
      `https://news.google.com/rss/search?q=${encodeURIComponent(query)}&hl=en-US&gl=US&ceid=US:en`;
    const r = await fetch(rssUrl, {
      headers: { "User-Agent": "Mozilla/5.0 (compatible; MarketPulseBot/1.0)", Accept: "application/rss+xml, application/xml, text/xml" },
    });
    if (r.ok) {
      const xml = await r.text();
      const items = [...xml.matchAll(/<item>([\s\S]*?)<\/item>/gi)].slice(0, limit + 2);
      const hits: SearchHit[] = [];
      for (const m of items) {
        const block = m[1];
        const title = decodeXml((block.match(/<title>([\s\S]*?)<\/title>/i)?.[1] || "").trim());
        const link = decodeXml((block.match(/<link>([\s\S]*?)<\/link>/i)?.[1] || "").trim());
        const desc = stripTags(decodeXml((block.match(/<description>([\s\S]*?)<\/description>/i)?.[1] || "").trim()));
        if (link) hits.push({ title, description: desc.slice(0, 400), url: link });
      }
      if (hits.length) return hits.slice(0, limit);
    }
  } catch (e) {
    console.warn("google news rss fail", query, e);
  }

  // Free: DuckDuckGo HTML
  try {
    const r = await fetch(`https://html.duckduckgo.com/html/?q=${encodeURIComponent(query)}`, {
      headers: {
        "User-Agent": "Mozilla/5.0 (compatible; MarketPulseBot/1.0)",
        Accept: "text/html",
      },
    });
    if (r.ok) {
      const html = await r.text();
      const hits: SearchHit[] = [];
      const re = /<a[^>]+class="result__a"[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>[\s\S]*?(?:class="result__snippet"[^>]*>([\s\S]*?)<\/(?:a|td|div)>)?/gi;
      let m: RegExpExecArray | null;
      while ((m = re.exec(html)) && hits.length < limit) {
        let href = m[1];
        // DDG wraps redirects: //duckduckgo.com/l/?uddg=<encoded>
        const uddg = href.match(/[?&]uddg=([^&]+)/);
        if (uddg) href = decodeURIComponent(uddg[1]);
        hits.push({
          title: stripTags(m[2]),
          description: stripTags(m[3] || "").slice(0, 400),
          url: href,
        });
      }
      if (hits.length) return hits;
    }
  } catch (e) {
    console.warn("duckduckgo search fail", query, e);
  }

  return [];
}

/** Build markdown context from mixed sources (ideas + urls + keywords). */
export async function gatherSourceContext(
  sources: SourceInput[],
  opts: GatherOptions = {},
): Promise<{ context: string; freshUrls: string[]; provider: "firecrawl" | "open" }> {
  const firecrawlKey = resolveFirecrawlKey(opts.firecrawlKey);
  const provider = firecrawlKey ? "firecrawl" : "open";
  const maxUrls = opts.maxUrls ?? 4;
  const maxKeywords = opts.maxKeywords ?? 4;
  const snippet = opts.urlSnippetChars ?? 2500;
  const used = opts.usedUrls ?? new Set<string>();
  const chunks: string[] = [];
  const freshUrls: string[] = [];

  const ideas = sources.filter((s) => s.type === "idea").map((s) => s.value).filter(Boolean);
  if (ideas.length) chunks.push(`# Ideas / notes from the user\n\n${ideas.map((i) => `- ${i}`).join("\n")}`);

  const urls = sources.filter((s) => s.type === "url").map((s) => s.value).filter(Boolean).slice(0, maxUrls);
  const keywords = sources.filter((s) => s.type === "keyword").map((s) => s.value).filter(Boolean).slice(0, maxKeywords);

  await Promise.all(urls.map(async (url) => {
    const md = await scrapeUrl(url, firecrawlKey);
    if (md) {
      chunks.push(`# Source: ${url}\n\n${md.substring(0, snippet)}`);
      freshUrls.push(url);
    }
  }));

  await Promise.all(keywords.map(async (kw) => {
    const results = await searchKeyword(kw, firecrawlKey, used.size ? 5 : 3);
    const fresh = results.filter((x) => x.url && !used.has(x.url)).slice(0, 3);
    if (!fresh.length) return;
    const summary = fresh.map((x) => `- ${x.title}: ${x.description} (${x.url})`).join("\n");
    chunks.push(`# Search: ${kw}\n\n${summary}`);
    for (const x of fresh) freshUrls.push(x.url);
  }));

  return { context: chunks.join("\n\n---\n\n"), freshUrls, provider };
}
